const upsertResourceACL = `-- name: UpsertResourceACL :exec
INSERT INTO resource_acl (account_id, resource_type, resource_id, user_id, role)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (resource_type, resource_id, user_id)
DO UPDATE SET role = EXCLUDED.role
`

type UpsertResourceACLParams struct {
	AccountID    uuid.UUID  `json:"account_id"`
	ResourceType string     `json:"resource_type"`
	ResourceID   uuid.UUID  `json:"resource_id"`
	UserID       *uuid.UUID `json:"user_id"`
	Role         string     `json:"role"`
}

func (q *Queries) UpsertResourceACL(ctx context.Context, arg UpsertResourceACLParams) error {
	_, err := q.db.Exec(ctx, upsertResourceACL,
		arg.AccountID,
		arg.ResourceType,
		arg.ResourceID,
		arg.UserID,
		arg.Role,
	)
	return err
}
